(* [comment removed for export] *)
Lemma xpres_of_munch_gen : forall HI LB SP X W m m',
  munch W m m' -> wmono asegs m m' ->
  (forall a, 0 <= a < 2^64 -> xclient HI LB SP X a -> outside W a) ->
  xpres HI LB SP X m m'.
Proof.
  intros HI LB SP X W m m' MU WM HO a Ha Hc. split.
  - unfold wa. apply MU. rewrite unsigned_lit by lia. apply HO; assumption.
  - intros Hw. apply WM. exact Hw.
Qed.

