  Lemma fresh_block_outside : forall s' LB m' p A n SP a,
    as_RHEAP HI s' ((p, A, n) :: LB) m' -> aceil <= SP -> aclient_addr HI LB SP a -> a + 1 <= A \/ A + n <= a.
  Proof.
    intros s' LB m' p A n SP a HP CE HC.
    eapply fresh_block_disjoint_client; [exact HP| apply aclient_addr_range; exact HC| exact CE| lia].
  Qed.

  (* [comment removed for export] *)
  Lemma high_off_errno : forall A n, AHI_LO <= A -> A + n <= AERRNO \/ AERRNO + 4 <= A.
  Proof. intros A n HA. right. unfold AERRNO, ATP, AHI_LO in *. lia. Qed.
  (* [comment removed for export] *)
  Lemma app_off_errno : forall A n, AIMG_TOP <= A -> A + n <= AERRNO \/ AERRNO + 4 <= A.
  Proof. intros A n HA. right. unfold AERRNO, ATP, AIMG_TOP in *. lia. Qed.
End CR.

Lemma bptr_eq_dec : forall x y : bptr, {x = y} + {x <> y}.
Proof. exact Z.eq_dec. Qed.

Section LBR.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  Lemma ah_lb_remove_cons_ne : forall p b LB, blk_id b <> p -> as_lb_remove H p (b :: LB) = b :: as_lb_remove H p LB.
  Proof. intros. apply (proj1 (proj2 (ah_lb_remove H HH))). assumption. Qed.

  Lemma ah_lb_remove_In : forall p LB b, In b (as_lb_remove H p LB) -> In b LB.
  Proof. intros. eapply (proj2 (proj2 (ah_lb_remove H HH))). eassumption. Qed.

  Lemma ah_lb_remove_keep : forall p LB b,
    List.NoDup (map blk_id LB) -> In b LB -> blk_id b <> p -> In b (as_lb_remove H p LB).
  Proof.
    intros p LB. induction LB as [|c LB IH]; intros b ND Hin NE; [destruct Hin|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct (bptr_eq_dec (blk_id c) p) as [E|NE'].
    - destruct c as [[pc Ac] nc]. cbn in E. subst pc.
      rewrite (proj1 (ah_lb_remove H HH)) by exact NI.
      destruct Hin as [<-|Hin]; [cbn in NE; congruence| exact Hin].
    - rewrite ah_lb_remove_cons_ne by exact NE'. destruct Hin as [<-|Hin]; [left; reflexivity| right]. apply IH; assumption.
  Qed.

  (* [comment removed for export] *)
  Lemma ah_lb_remove_fresh : forall s LB m p' A' n' p,
    as_RHEAP H s ((p', A', n') :: LB) m -> In p (map blk_id LB) ->
    as_lb_remove H p ((p', A', n') :: LB) = (p', A', n') :: as_lb_remove H p LB.
  Proof.
    intros s LB m p' A' n' p HP Hin. apply ah_lb_remove_cons_ne. cbn.
    pose proof (ah_nodup H HH _ _ _ HP) as ND. cbn in ND. inversion ND; subst. congruence.
  Qed.

  (* [comment removed for export] *)
  Lemma nodup_blk_eq : forall LB b b', List.NoDup (map blk_id LB) -> In b LB -> In b' LB -> blk_id b = blk_id b' -> b = b'.
  Proof.
    induction LB as [|c LB IH]; intros b b' ND Hb Hb' E; [destruct Hb|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct Hb as [<-|Hb]; destruct Hb' as [<-|Hb']; [reflexivity| | | apply IH; assumption].
    - exfalso. apply NI. rewrite E. apply in_map. exact Hb'.
    - exfalso. apply NI. rewrite <- E. apply in_map. exact Hb.
  Qed.

  (* [comment removed for export] *)
  Lemma aclient_range_after_free : forall s LB m p Ap np s2 m2 p' A' n' SP A n,
    as_RHEAP H s LB m -> In (p, Ap, np) LB -> as_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    aclient_range H LB SP A n -> (A + n <= Ap \/ Ap + np <= A) -> (A + n <= sh Ap \/ sh Ap + nsh np <= A) -> 0 < n ->
    aclient_range H (as_lb_remove H p ((p', A', n') :: LB)) SP A n.
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' SP A n HP Hin HP2 HR DJ DJS Hn.
    rewrite (ah_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    unfold aclient_range in *.
    destruct HR as [K|[K|[(b & Hb & K1 & K2)|[(b & Hb & K1 & K2)|K]]]]; [left; exact K| right; left; exact K| | | right; right; right; right; exact K].
    - right; right; left. exists b. split; [| split; assumption]. right.
      apply ah_lb_remove_keep; [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K1, K2.
      pose proof (ah_blocks H HH _ _ _ _ HP Hin) as (_ & _ & R3 & _). cbn in R3. lia.
    - right; right; right; left. exists b. split; [| split; assumption]. right.
      apply ah_lb_remove_keep; [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K1, K2.
      pose proof (ah_blocks H HH _ _ _ _ HP Hin) as (_ & _ & R3 & _). cbn in R3. unfold nsh in *. lia.
  Qed.

  Lemma xpres_after_free : forall s LB m p Ap np s2 m2 p' A' n' SP SP' X m3 m4,
    as_RHEAP H s LB m -> In (p, Ap, np) LB -> as_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    apres H (as_lb_remove H p ((p', A', n') :: LB)) SP' m3 m4 -> SP' <= SP ->
    (forall a, Ap <= a < Ap + np -> rin_ivs X a) ->
    (forall a, sh Ap <= a < sh Ap + nsh np -> rin_ivs X a) ->     (* [comment removed for export] *)
    xpres H LB SP X m3 m4.
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' SP SP' X m3 m4 HP Hin HP2 PRES HS HX HXS a Ha [HC NX].
    apply PRES; [exact Ha|].
    rewrite (ah_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    unfold aclient_addr in *.
    destruct HC as [K|[K|[(b & Hb & K)|[(b & Hb & K)|K]]]]; [left; lia| right; left; exact K| | | right; right; right; right; exact K].
    - right; right; left. exists b. split; [| exact K]. right.
      apply ah_lb_remove_keep; [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K. apply NX. apply HX. exact K.
    - right; right; right; left. exists b. split; [| exact K]. right.
      apply ah_lb_remove_keep; [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K. apply NX. apply HXS. exact K.
  Qed.

  (* [comment removed for export] *)
  Lemma fresh_in_after_free : forall s LB m p Ap np s2 m2 p' A' n',
    as_RHEAP H s LB m -> In (p, Ap, np) LB -> as_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    In (p', A', n') (as_lb_remove H p ((p', A', n') :: LB))
    /\ (forall b, In b (as_lb_remove H p ((p', A', n') :: LB)) -> In b ((p', A', n') :: LB)).
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' HP Hin HP2.
    rewrite (ah_lb_remove_fresh _ _ _ _ _ _ _ HP2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    split; [left; reflexivity|]. intros b [<-|Hb]; [left; reflexivity| right]. eapply ah_lb_remove_In. exact Hb.
  Qed.
