  (* [comment removed for export] *)
  Lemma client_frame3 : forall s LB LF W m m',
    as_RHEAP H s LB m -> as_RFS H LF m -> ACONST m ->
    munch W m m' -> wmono asegs m m' ->
    Forall (aclient_write_ok H LB) W -> Forall (afs_write_ok H LF) W -> Forall aconst_ok W ->
    as_RHEAP H s LB m' /\ as_RFS H LF m' /\ ACONST m'.
  Proof.
    intros s LB LF W m m' RH RF AC MU WM F1 F2 F3.
    split; [eapply (ah_RHEAP_frame H HH); eauto|]. split; [eapply (ah_RFS_frame H HH); eauto| eapply ACONST_frame; eauto].
  Qed.

  Lemma stack_window_ok' : forall s LB m LF lo' SP,
    as_RHEAP H s LB m -> aceil <= lo' ->
    aclient_write_ok H LB (lo', SP) /\ afs_write_ok H LF (lo', SP) /\ aconst_ok (lo', SP).
  Proof.
    intros s LB m LF lo' SP RH CE. pose proof (ah_fsb H HH _ _ _ RH) as (F1 & F2 & F3).
    apply (stack_window_ok H); [exact CE| exact F2].
  Qed.

