Lemma disjoint_from_Forall : forall XS a n, disjoint_from XS a n <-> Forall (fun iv : Z * Z => a + n <= fst iv \/ snd iv <= a) XS.
Proof.
  induction XS as [|[l h] XS IH]; intros a n; cbn.
  - split; [intros _; constructor| intros _; exact I].
  - split.
    + intros [K1 K2]. constructor; [cbn; exact K1| apply IH; exact K2].
    + intros K. pose proof (Forall_inv K) as K1. cbn in K1. split; [exact K1| apply IH; exact (Forall_inv_tail K)].
Qed.

