  (* [comment removed for export] *)
  Lemma aobj_aclient_range : forall LF LB m1 SP A n, as_RFS H LF m1 -> aobj LB LF A n -> aclient_range H LB SP A n.
  Proof.
    intros LF LB m1 SP A n RF [(b & Hb & H1 & H2)|(f & Hf & H1 & H2)]. all: aapp_facts.
    - right; right; left. exists b. auto.
    - pose proof (proj2 (ah_RFS_range H HH _ _ RF) f Hf) as (K & R1 & R2 & R3 & R4); pose proof (proj1 (ah_RFS_range H HH _ _ RF)) as (F1 & F2 & F3).
      right; right; right; right; left. unfold AFS_HDR in *. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma fresh_vs_aobj : forall LF s' L' m' m1 p A n O k,
    as_RHEAP H s' ((p, A, n) :: L') m' -> as_RFS H LF m1 -> aobj L' LF O k -> 0 < k -> O + k <= A \/ A + n <= O.
  Proof.
    intros LF s' L' m' m1 p A n O k HP RF AO Hk. all: aapp_facts.
    eapply (fresh_block_disjoint_client H HH); [exact HP| eapply (aobj_aclient_range LF L' m1 aceil); [exact RF| exact AO]| lia| exact Hk].
  Qed.

