Section ARR.
  Context {HCEIL : HeapCeil}.

Lemma xpres_u32arr : forall H LB SP X m m' A ws,
  xpres H LB SP X m m' -> u32arr asegs m A ws -> xclient_range H LB SP X A (4 * Z.of_nat (length ws)) -> u32arr asegs m' A ws.
Proof.
  intros H LB SP X m m' A ws XP [B W] R. all: aapp_facts. split.
  - eapply xpres_bytes_at; [exact XP| exact B|]. rewrite u32s_length. replace (Z.of_nat (4 * length ws)) with (4 * Z.of_nat (length ws)) by lia. exact R.
  - eapply xpres_wr_at; [exact XP| exact W| exact R].
Qed.

Lemma xpres_u64arr : forall H LB SP X m m' A ws,
  xpres H LB SP X m m' -> u64arr asegs m A ws -> xclient_range H LB SP X A (8 * Z.of_nat (length ws)) -> u64arr asegs m' A ws.
Proof.
  intros H LB SP X m m' A ws XP [B W] R. all: aapp_facts. split.
  - eapply xpres_bytes_at; [exact XP| exact B|]. rewrite u64s_length. replace (Z.of_nat (8 * length ws)) with (8 * Z.of_nat (length ws)) by lia. exact R.
  - eapply xpres_wr_at; [exact XP| exact W| exact R].
Qed.

(* [comment removed for export] *)
Lemma xpres_reLB : forall H LB LB1 SP SP1 X X1 m m',
  xpres H LB1 SP1 X1 m m' ->
  (forall a, 0 <= a < 2^64 -> aclient_addr H LB SP a -> ~ rin_ivs X a -> aclient_addr H LB1 SP1 a /\ ~ rin_ivs X1 a) ->
  xpres H LB SP X m m'.
Proof. intros H LB LB1 SP SP1 X X1 m m' XP HC a Ha [C NX]. apply XP; [exact Ha|]. destruct (HC a Ha C NX) as [C1 N1]. split; assumption. Qed.

End ARR.

