  (* [comment removed for export] *)
  Definition noshadow (iv : Z * Z) : Prop := snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv.

  Lemma noshadow_avoid_sh : forall X b n, Forall noshadow X -> 0 <= b -> 0 <= n -> b + n <= AAPP_HI ->
    Forall (fun iv : Z * Z => sh b + nsh n <= fst iv \/ snd iv <= sh b) X.
  Proof.
    intros X b n FX Hb Hn Htop. pose proof (sh_nsh_high b n Hb Hn Htop) as S1. pose proof (sh_ge_lowsh b Hb) as S2.
    assert (S3 : ALOWSH_LO < sh b) by (unfold sh, ALOWSH_LO; rewrite ASHADOW_BASE_val; Z.div_mod_to_equations; lia).
    eapply Forall_impl; [| exact FX]. intros [l h] K. unfold noshadow in K. cbn in *. lia.
  Qed.

  Lemma awin_noshadow : forall W, Forall awin W -> Forall noshadow W.
  Proof. intros W FW. eapply Forall_impl; [| exact FW]. intros iv (_ & _ & K). exact K. Qed.

  (* [comment removed for export] *)
  Lemma awin_sh_disjoint : forall W b n, Forall awin W -> 0 <= b -> 0 <= n -> b + n <= AAPP_HI -> disjoint_from W (sh b) (nsh n).
  Proof.
    intros W b n FW Hb Hn Htop. apply awin_disjoint_shland; [exact FW| apply sh_ge_lowsh; exact Hb| apply sh_nsh_high; assumption].
  Qed.

  Lemma rblock_bounds : forall b n, rblock_range b n -> 0 <= b /\ 0 <= n /\ b + n <= AAPP_HI /\ AIMG_TOP <= b /\ b + n <= aceil /\ b mod 8 = 0.
  Proof.
    intros b n (R1 & R2 & R3 & R4 & R5). pose proof (aapp_bounds _ _ R4 R3) as (B1 & B2 & B3 & B4 & B5).
    repeat split; first [lia | clear - R2; Z.div_mod_to_equations; lia].
  Qed.

  (* [comment removed for export] *)
  Lemma xclient_range_img : forall LB SP X A n,
    (forall a, A <= a < A + n -> aimg_client a) -> Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) X ->
    xclient_range H LB SP X A n.
  Proof. intros LB SP X A n IMG FX. split; [right; left; exact IMG| exact FX]. Qed.

