  (* [comment removed for export] *)
  Lemma rw_cells_xpres_hi : forall LB SP X m m' A cs,
    xpres H LB SP X m m' -> rw_cells asegs m A cs -> SP <= A ->
    Forall (fun iv : Z * Z => A + Z.of_nat (cells_size cs) <= fst iv \/ snd iv <= A) X ->
    rw_cells asegs m' A cs.
  Proof. intros LB SP X m m' A cs PRES RC HA FX. eapply xpres_rw_cells; [exact PRES | exact RC |]. split; [left; exact HA | exact FX]. Qed.

  Lemma bytes_at_xpres : forall LB SP X m m' A bs,
    xpres H LB SP X m m' -> bytes_at asegs m A bs -> aclient_range H LB SP A (Z.of_nat (length bs)) ->
    Forall (fun iv : Z * Z => A + Z.of_nat (length bs) <= fst iv \/ snd iv <= A) X ->
    bytes_at asegs m' A bs.
  Proof. intros LB SP X m m' A bs PRES BA RR FX. eapply xpres_bytes_at; [exact PRES | exact BA |]. split; [exact RR | exact FX]. Qed.

  Lemma ro_cells_xpres : forall LB SP X m m' A cs,
    xpres H LB SP X m m' -> ro_cells asegs m A cs -> xclient_range H LB SP X A (Z.of_nat (cells_size cs)) -> ro_cells asegs m' A cs.
  Proof.
    intros LB SP X m m' A cs XP [Hwf HB] HR. split; [exact Hwf|].
    eapply xpres_bytes_at; eauto. rewrite cells_bytes_length by assumption. exact HR.
  Qed.

  (* [comment removed for export] *)
  Lemma aobj_fsobj : forall s LB m0 LF A n, as_RHEAP H s LB m0 -> aobj LB LF A n -> fsobj H LF A n.
  Proof.
    intros s LB m0 LF A n RH [(b & Hb & H1 & H2)|(f & Hf & H1 & H2)].
    - destruct b as [[p Ab] nb]. cbn in H1, H2. eapply fsobj_sub; [eapply (fsobj_block H HH); [exact RH| exact Hb] | exact H1| exact H2].
    - eapply fsobj_inframe; eauto.
  Qed.

  Lemma xclient_range_aobj : forall s LB m0 LF m1 SP X XS O n,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF O n -> 0 <= n ->
    Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) X -> Forall (fs_scratch H LF) XS ->
    xclient_range H LB SP (X ++ XS) O n.
  Proof.
    intros s LB m0 LF m1 SP X XS O n RH RF AO Hn FX FS.
    pose proof (aobj_aapp H HH _ _ _ _ _ _ _ RH RF AO) as AP. pose proof (aapp_bounds _ _ AP Hn) as (B1 & B2 & B3 & B4 & B5).
    split; [exact (aobj_client H HH s LB m0 LF m1 SP O n RH RF AO)|]. apply Forall_app. split; [exact FX|].
    eapply (Forall_scratch H HH); [exact RF| eapply aobj_fsobj; eauto| exact Hn| lia| exact AP| exact FS].
  Qed.

