  Lemma aobj_xpres_accessible : forall s LB m0 LF m1 SP X XS m m' O n a k,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF O n -> 0 <= n ->
    xpres H LB SP (X ++ XS) m m' -> Forall noshadow X -> Forall (fs_scratch H LF) XS ->
    accessible m a k -> O <= a -> a + k <= O + n -> accessible m' a k.
  Proof.
    intros s LB m0 LF m1 SP X XS m m' O n a k RH RF AO Hn XP FX FS AC H1 H2.
    eapply (xpres_accessible H); [exact XP| exact AC|]. intros x Hx. eapply xclient_sh_aobj; eauto. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma blk_xpres_addressable : forall s LB m0 LF m1 SP X XS m m' p A n,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> In (p, A, n) LB ->
    xpres H LB SP (X ++ XS) m m' -> Forall noshadow X -> Forall (fs_scratch H LF) XS ->
    addressable m A n -> addressable m' A n.
  Proof.
    intros s LB m0 LF m1 SP X XS m m' p A n RH RF IN XP FX FS AD. pose proof AD as [Hn _].
    pose proof (ah_blocks H HH _ _ _ _ RH IN) as (R1 & R2 & R3 & R4 & R5 & R6 & R7). cbn in R1, R2, R3, R4, R5, R6, R7.
    pose proof (aapp_bounds _ _ R7 R3) as (B1 & B2 & B3 & B4 & B5).
    eapply (xpres_addressable H); [exact XP| exact AD|]. split; [eapply aclient_range_block_sh; exact IN|].
    apply Forall_app. split.
    - apply noshadow_avoid_sh; [exact FX| lia| lia| lia].
    - eapply (Forall_scratch_sh H HH); [exact RF| eapply (fsobj_block H HH); [exact RH| exact IN] | lia| lia| exact R7| exact FS].
  Qed.

  (* [comment removed for export] *)
  Lemma lb_remove_exact : forall p A n LB,
    List.NoDup (map blk_id LB) -> In (p, A, n) LB ->
    lb_bytes (as_lb_remove H p LB) = lb_bytes LB - n
    /\ (S (length (as_lb_remove H p LB)) = length LB)%nat
    /\ (forall b, In b (as_lb_remove H p LB) <-> (In b LB /\ blk_id b <> p)).
  Proof.
    intros p A n LB. induction LB as [|c LB IH]; intros ND Hin; [destruct Hin|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct Hin as [->|Hin].
    - cbn in NI. rewrite (proj1 (ah_lb_remove H HH)) by exact NI. rewrite lb_bytes_cons. cbn [blk_size snd length].
      split; [lia|]. split; [reflexivity|].
      intros b. split.
      + intros Hb. split; [right; exact Hb|]. intros E. apply NI. apply in_map_iff. exists b. split; [exact E| exact Hb].
      + intros [[<-|Hb] NE]; [cbn in NE; congruence| exact Hb].
    - assert (NE : blk_id c <> p).
      { intros E. apply NI. apply in_map_iff. exists (p, A, n). split; [symmetry; exact E| exact Hin]. }
      rewrite (ah_lb_remove_cons_ne H HH) by exact NE. rewrite !lb_bytes_cons. cbn [length].
      destruct (IH ND' Hin) as (B1 & B2 & B3). split; [lia|]. split; [lia|].
      intros b. split.
      + intros [<-|Hb]; [split; [left; reflexivity| exact NE]|]. destruct (proj1 (B3 b) Hb) as [K1 K2]. split; [right; exact K1| exact K2].
      + intros [[<-|Hb] NEb]; [left; reflexivity| right]. apply (proj2 (B3 b)). split; [exact Hb| exact NEb].
  Qed.

  (* [comment removed for export] *)
  Lemma aobj_lb_remove : forall s LB m LF p Ap np A n,
    as_RHEAP H s LB m -> In (p, Ap, np) LB -> aobj LB LF A n -> (A + n <= Ap \/ Ap + np <= A) -> 0 < n ->
    aobj (as_lb_remove H p LB) LF A n.
  Proof.
    intros s LB m LF p Ap np A n RH Hin AO DJ Hn.
    destruct AO as [(b & Hb & H1 & H2)|K]; [left| right; exact K]. exists b. split; [| split; assumption].
    apply (ah_lb_remove_keep H HH); [exact (ah_nodup H HH _ _ _ RH)| exact Hb|].
    intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ RH)| exact Hb| exact Hin| exact E]).
    subst b. cbn in H1, H2. pose proof (ah_blocks H HH _ _ _ _ RH Hin) as (_ & _ & R3 & _). cbn in R3. lia.
  Qed.

