  Lemma chain_nil_aapp : forall m A n, aapp A n -> 0 <= n -> as_chain H m A [].
  Proof. intros m A n AP Hn. apply (ah_chain_nil H HH). left. pose proof (aapp_below_aceil _ _ AP). lia. Qed.
  Lemma chain_nil_low : forall m c, c <= aceil -> as_chain H m c [].
  Proof. intros m c Hc. apply (ah_chain_nil H HH). left. exact Hc. Qed.
  Lemma chain_nil_odd : forall m c, c mod 8 <> 0 -> as_chain H m c [].
  Proof. intros m c Hc. apply (ah_chain_nil H HH). right. exact Hc. Qed.

