  Lemma AStateBlock_transport_awin : forall W LB m m' b ioc implb S ds,
    AStateBlock LB m b ioc implb S ds -> munch W m m' -> wmono asegs m m' -> Forall awin W -> disjoint_from W b SZ_SPCI_STATE ->
