  Lemma AImplBlock_xpres : forall LB SP X m m' b I,
    AImplBlock LB m b I -> xpres H LB SP X m m' ->
    Forall (fun iv : Z * Z => b + SZ_SPCI_IMPL <= fst iv \/ snd iv <= b) X ->
    Forall (fun iv : Z * Z => sh b + nsh SZ_SPCI_IMPL <= fst iv \/ snd iv <= sh b) X ->
    (0 < im_vcap I -> Forall (fun iv : Z * Z => im_vb I + 8 * im_vcap I <= fst iv \/ snd iv <= im_vb I) X) ->
    (0 < im_vcap I -> Forall (fun iv : Z * Z => sh (im_vb I) + nsh (8 * im_vcap I) <= fst iv \/ snd iv <= sh (im_vb I)) X) ->
    AImplBlock LB m' b I.
  Proof.
    intros LB SP X m m' b I (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST & AD) XP FX FXS FV FVS. exists p, j7.
    pose proof (blk_xclient_range LB SP X p b SZ_SPCI_IMPL) as XR. specialize (fun A k => XR A k IN FX).
    assert (AD' : addressable m' b SZ_SPCI_IMPL) by (xp_addr XP AD IN FXS). clear AD FXS.
    unfold SZ_SPCI_IMPL, O_SPC_STORAGE, O_IMPL_MUTEX, O_IMPL_VEC_BEGIN in *.
    split; [exact IN|]. split; [exact RB|]. split; [xp_keep XP XR|]. split; [exact OK|]. split; [exact EV|].
    split. { destruct PM as (PMC & LK & AL). split; [| split; [exact LK| exact AL]]. xp_keep XP XR. }
    split; [xp_keep XP XR|]. split; [exact LE|]. split; [| exact AD'].
    destruct ST as [ST|(q & junk & INq & RBq & POS & CS & ADq)]; [left; exact ST| right]. exists q, junk.
    split; [exact INq|]. split; [exact RBq|]. split; [exact POS|].
    split; [| eapply (xpres_addressable H); [exact XP| exact ADq| split; [eapply aclient_range_block_sh; exact INq| exact (FVS POS)]]].
    pose proof (rw_cells_bound _ _ _ _ CS) as B. destruct CS as [[WF BA] WR]. cbn in WF.
    eapply xpres_rw_cells; [exact XP| split; [split; [exact WF| exact BA] | exact WR] |].
    cbn [cells_size csize Nat.add] in *. split.
    - right; right; left. exists (q, im_vb I, 8 * im_vcap I). split; [exact INq| cbn; unfold zlength in *; lia].
    - eapply Forall_impl; [| exact (FV POS)]. intros [lo hi] K; cbn in *; unfold zlength in *; lia.
  Qed.

  Lemma AStateBlock_xpres : forall LB SP X m m' b ioc implb S ds,
    AStateBlock LB m b ioc implb S ds -> xpres H LB SP X m m' ->
    Forall (fun iv : Z * Z => b + SZ_SPCI_STATE <= fst iv \/ snd iv <= b) X ->
    Forall (fun iv : Z * Z => sh b + nsh SZ_SPCI_STATE <= fst iv \/ snd iv <= sh b) X ->
    (st_fb S <> FB_empty -> Forall (fun iv : Z * Z => fb_end (st_fb S) <= fst iv \/ snd iv <= fb_begin (st_fb S)) X) ->
    (st_fb S <> FB_empty -> Forall (fun iv : Z * Z => sh (fb_begin (st_fb S)) + nsh (fb_cap (st_fb S)) <= fst iv \/ snd iv <= sh (fb_begin (st_fb S))) X) ->
    AStateBlock LB m' b ioc implb S ds.
